import type { AppIcon } from "apps";

// Generated by scripts/icon.ts from the vendor's logo.
export const icons: readonly AppIcon[] = [
  {
    "src": "data:image/svg+xml;base64,",
    "mimeType": "image/svg+xml"
  }
];

import {
  ProviderError,
  accountRouter,
  array,
  decodeJson,
  defineApp,
  defineProvider,
  json,
  number,
  object,
  query,
  router,
  secrets,
  string,
  withApprovals,
} from "apps";
import { always } from "apps/operations/approval";
import { liveOpenapiRouter } from "apps/openapi";
import { icons } from "./icon.js";
import { options } from "./openapi.js";

const exa = defineProvider({
  name: "Exa",
  hosts: ["api.exa.ai"],
  auth: {
    apiKey: secrets({
      label: "API key",
      fields: object({ token: string({ minLength: 1 }) }),
    }),
  },
  // GET /v0/teams/me is a read-only account endpoint. Exa's OpenAPI document serves it from the
  // Websets server (an operation-level `servers` entry); the API root answers 404 for every key.
  // Only 401 and 403 mean Exa refused the key; any other answer leaves it unverified.
  async health({ account, fetch, signal }) {
    const response = await fetch("https://api.exa.ai/websets/v0/teams/me", {
      signal,
      headers: { "x-api-key": account.fields.token },
    });
    if (response.status === 401) throw new ProviderError({ reason: "unauthorized", status: 401 });
    if (response.status === 403) throw new ProviderError({ reason: "rejected", status: 403 });
    if (response.status === 429) throw new ProviderError({ reason: "rate_limited", status: 429 });
    if (response.status >= 500)
      throw new ProviderError({ reason: "unavailable", status: response.status });
    if (!response.ok) throw new Error(`Exa's account check answered HTTP ${response.status}.`);
  },
});

const post = async (
  fetch: typeof globalThis.fetch,
  signal: AbortSignal,
  token: string,
  path: string,
  body: unknown,
) =>
  decodeJson(
    await fetch(`https://api.exa.ai${path}`, {
      method: "POST",
      signal,
      headers: { "content-type": "application/json", "x-api-key": token },
      body: JSON.stringify(body),
    }),
    json(),
  );

const UserLocation = string().optional();

// The spec marks POST /search and POST /answer as server-sent-event responses, so the
// generator drops them. These tools call them with stream=false, which returns plain JSON.
const exaCustom = (account: { fields: { token: string } }, signal: AbortSignal) =>
  router({
    search: query(
      {
        description:
          "Search the web with Exa. Returns results with title, url, published date and optional page contents. Set `type` to auto, fast, instant, deep-lite, deep or deep-reasoning.",
        input: object({
          query: string(),
          type: string().optional(),
          category: string().optional(),
          numResults: number().optional(),
          includeDomains: array(string()).optional(),
          excludeDomains: array(string()).optional(),
          startPublishedDate: string().optional(),
          endPublishedDate: string().optional(),
          userLocation: UserLocation,
          contents: json().optional(),
        }),
      },
      async ({ fetch }, input) =>
        post(fetch, signal, account.fields.token, "/search", { ...input, stream: false }),
    ),
    answer: query(
      {
        description:
          "Get an answer to a question grounded in a web search, with citations. Returns the answer and the cited sources.",
        input: object({
          query: string(),
          text: json().optional(),
          model: string().optional(),
          systemPrompt: string().optional(),
          outputSchema: json().optional(),
        }),
      },
      async ({ fetch }, input) =>
        post(fetch, signal, account.fields.token, "/answer", { ...input, stream: false }),
    ),
  });

export default defineApp(
  { user: { accounts: { exa: exa.many() } }, icons },
  async ({ user, cache, fetch, signal }) => ({
    tools: router(
      {
        api: await accountRouter(
          user?.accounts.exa ?? [],
          (account) =>
            withApprovals(liveOpenapiRouter({ ...options, cache, fetch, signal, account }), (tool) =>
              tool.kind === "mutation" ? always() : undefined,
            ),
          { signal },
        ),
        custom: await accountRouter(user?.accounts.exa ?? [], (account) => exaCustom(account, signal), { signal }),
      },
      {
        title: "Exa",
        description: "AI web search with Exa: search, find similar pages, fetch page contents, get cited answers, and manage monitors, agent runs, batches and websets.",
        icons,
      },
    ),
  }),
);

import type { OpenapiToolNamesOptions } from "apps/openapi";

export const options = {
  source: { url: "https://api.exa.ai/openapi.json" },
  allowedOrigin: "https://api.exa.ai",
  securitySchemes: {
    apiKey: { type: "apiKey", name: "x-api-key", in: "header" },
    bearer: { type: "http", scheme: "bearer" },
  },
  methods: { apiKey: [{ scheme: "apiKey", field: "token", part: "value", prefix: "" }] },
  oauth: [],
  // Exa models these reads as POST. They change nothing (they spend search credits), so they are
  // queries; every other POST, PATCH and DELETE stays a mutation and asks for approval.
  kinds: { search: "query", getContents: "query", findSimilar: "query", answer: "query" },
} satisfies OpenapiToolNamesOptions;

{
  "name": "@executor.sh/exa",
  "description": "AI web search with Exa: search, find similar pages, fetch page contents, get cited answers, and manage monitors, agent runs, batches and websets.",
  "private": true,
  "type": "module",
  "dependencies": {
    "apps": "0.0.1-beta.104-basalt.15"
  },
  "executor": {
    "title": "Exa"
  }
}
